      "glossary": [
        {
          "term": "Trapped-ion qubits",
          "definition": "IonQ's qubit modality — ytterbium ions in electromagnetic traps, manipulated by lasers. Highest gate fidelity but slower clock than superconducting."
        },
        {
          "term": "AQ (Algorithmic Qubits)",
          "definition": "IonQ's benchmark for usable capacity. AQ#N = circuits requiring 2^N states. AQ#64 hit 2026; AQ#256 targeted 2027."
        },
        {
          "term": "Quantum advantage",
          "definition": "Quantum solving a problem faster/cheaper than classical. Google's Willow demonstrated verifiable advantage on chemistry Oct 2025; no commercial advantage verified yet."
        },
        {
          "term": "Quantinuum",
          "definition": "Honeywell-backed full-stack trapped-ion competitor. Filed for $12.7B IPO May 2026; better logical-qubit performance (48 logical at 99.92%)."
        },
        {
          "term": "SkyWater",
          "definition": "US semiconductor foundry IonQ is acquiring (~$1.8B, closes Q2/Q3 2026). Domestic chip fab — enables 200K-qubit chip in 2028."
        },
        {
          "term": "Tempo / Forte",
          "definition": "IonQ system generations. Forte = current commercial (AQ#36). Tempo = next-gen, AQ#64 demonstrated, 256-qubit chip."
        }
      ],
